+(function () {
+  const form = document.getElementById('consent-form');
+  const checkbox = document.getElementById('agree-terms');
+  const field = checkbox.closest('.form-field');
+  const errorEl = document.getElementById('agree-error');
+  const status = document.getElementById('form-status');
+
+  function setInvalid(invalid) {
+    if (invalid) {
+      checkbox.setAttribute('aria-invalid', 'true');
+      errorEl.hidden = false;
+      field.classList.add('is-invalid');
+    } else {
+      checkbox.removeAttribute('aria-invalid');
+      errorEl.hidden = true;
+      field.classList.remove('is-invalid');
+    }
+  }
+
+  checkbox.addEventListener('change', function () {
+    if (checkbox.checked) setInvalid(false);
+  });
+
+  form.addEventListener('submit', function (event) {
+    event.preventDefault();
+    status.textContent = '';
+
+    if (!checkbox.checked) {
+      setInvalid(true);
+      checkbox.focus();
+      return;
+    }
+
+    setInvalid(false);
+    status.textContent = 'Thanks! Your agreement has been recorded.';
+    form.reset();
+  });
+})();
+
